INSERT INTO "submissions" ("id","family_id","mission_id","attempt_number","payload_json","evidence_hash","suspicious_input_detected","evaluator_version","created_at") VALUES('2c61121f-9f33-4d21-8739-107eb4c70e9e','1225785f-3bdb-4847-bdca-4bdcc9c27788','V1-M04',4,'{"mission_id":"V1-M04","code":"local Players = game:GetService(\"Players\")\nlocal world = workspace:WaitForChild(\"World\")\nlocal npcs = world:WaitForChild(\"NPCs\")\nlocal selectedNPC = nil\nlocal selectionHighlight = Instance.new(\"Highlight\")\nselectionHighlight.Name = \"SelectedNPCHighlight\"\nselectionHighlight.Adornee = nil\nselectionHighlight.Parent = Players.LocalPlayer:WaitForChild(\"PlayerGui\")\nlocal function selectNPC(npc)\n  selectedNPC = npc\n  selectionHighlight.Adornee = npc\nend\nfor _, npcName in ipairs({\"NPC_1\", \"NPC_2\"}) do\n  local npc = npcs:WaitForChild(npcName)\n  local detector = npc:WaitForChild(\"HumanoidRootPart\"):WaitForChild(\"ClickDetector\")\n  detector.MouseClick:Connect(function() selectNPC(npc) end)\nend","explorer_summary":"CONTROLLED RELEASE TEST ORACLE: both canonical ClickDetectors exist; one CommandClient LocalScript owns selection; runtime inspection counted one SelectedNPCHighlight and two event connections.","output":"CONTROLLED RELEASE TEST ORACLE: fresh Play and restart completed with no project-code red errors; highlight count remained 1 after alternating clicks five times.","screenshots":["release-test-oracle://V1-M04/T01-one-highlight-on-NPC_1","release-test-oracle://V1-M04/T02-same-highlight-moved-to-NPC_2","release-test-oracle://V1-M04/T03-one-highlight-after-five-alternations","release-test-oracle://V1-M04/T04-fresh-restart-NPC_2-first"],"checklist":{"V1-M04-T01":true,"V1-M04-T02":true,"V1-M04-T03":true,"V1-M04-T04":true},"understanding":"selectedNPC is the one local variable that remembers which NPC should receive the next command.","release_test_attestation":{"kind":"controlled_fixture","expected_status":"APPROVED","visual_runtime_observed":true,"oracle_version":"worldmaker-release-fixture-v1","note":"Machine-observed release assertions, not fabricated screenshots; reachable only through the secret isolated endpoint."}}','305806b663cbeec6fa306c6f57f1edb85e317cbb831236c24a899fccbe2c6dd1',0,'v1-release-engine-2026-07-14','2026-07-15 01:00:54');
